import { NextResponse } from "next/server";
import { nextStep, resetGame, revealAnswer, startGame } from "@/lib/game-store";

export async function POST(request: Request) {
  const body = await request.json().catch(() => ({}));

  if (body.action === "start") return NextResponse.json(startGame());
  if (body.action === "reveal") return NextResponse.json(revealAnswer());
  if (body.action === "next") return NextResponse.json(nextStep());
  if (body.action === "reset") return NextResponse.json(resetGame());

  return NextResponse.json({ message: "Unknown host action" }, { status: 400 });
}
