import { questions, sleRounds } from "@/lib/quiz-data";

export const GAME_CODE = "AADIT";
export const QUESTION_SECONDS = 25;

export type Phase = "lobby" | "question" | "sle" | "leaderboard";
export type Player = { id: string; name: string; score: number; joinedAt: number };
export type AnswerRecord = Record<string, { choice: number; correct: boolean }>;

export type GameState = {
  phase: Phase;
  players: Player[];
  currentQuestion: number;
  revealed: boolean;
  answers: AnswerRecord;
  pendingSleIndex: number | null;
  questionStartedAt: number;
};

type Store = { state: GameState };

declare global {
  // Keeps the game alive across route handler reloads while the Next server runs.
  // eslint-disable-next-line no-var
  var aaditQuizStore: Store | undefined;
}

function initialState(): GameState {
  return {
    phase: "lobby",
    players: [],
    currentQuestion: 0,
    revealed: false,
    answers: {},
    pendingSleIndex: null,
    questionStartedAt: Date.now()
  };
}

function store() {
  globalThis.aaditQuizStore ??= { state: initialState() };
  return globalThis.aaditQuizStore;
}

function makePlayerId() {
  return `p_${Date.now()}_${Math.random().toString(16).slice(2)}`;
}

function cleanName(name: string) {
  return name.trim().replace(/[<>]/g, "").slice(0, 18) || "QoA Player";
}

function syncTimer(state: GameState) {
  if (state.phase !== "question" || state.revealed) return;

  if (timeLeftFor(state) <= 0) {
    state.revealed = true;
  }
}

export function timeLeftFor(state: GameState) {
  if (state.phase !== "question") return QUESTION_SECONDS;
  const elapsed = Math.floor((Date.now() - state.questionStartedAt) / 1000);
  return Math.max(0, QUESTION_SECONDS - elapsed);
}

export function getState() {
  const current = store().state;
  syncTimer(current);
  return { ...current, timeLeft: timeLeftFor(current), gameCode: GAME_CODE, questionCount: questions.length };
}

export function joinGame(name: string, code: string) {
  if (code.trim().toUpperCase() !== GAME_CODE) {
    return { ok: false as const, message: "That class code is not right yet." };
  }

  const current = store().state;
  const player = { id: makePlayerId(), name: cleanName(name), score: 0, joinedAt: Date.now() };
  current.players.push(player);
  return { ok: true as const, playerId: player.id, state: getState() };
}

export function startGame() {
  store().state = {
    ...initialState(),
    phase: "question",
    players: store().state.players.map((player) => ({ ...player, score: 0 })),
    questionStartedAt: Date.now()
  };

  return getState();
}

export function resetGame() {
  store().state = initialState();
  return getState();
}

export function revealAnswer() {
  const current = store().state;
  if (current.phase === "question") current.revealed = true;
  return getState();
}

export function submitAnswer(playerId: string, choice: number) {
  const current = store().state;
  syncTimer(current);

  if (current.phase !== "question" || current.revealed || current.answers[playerId]) {
    return getState();
  }

  const player = current.players.find((entry) => entry.id === playerId);
  const question = questions[current.currentQuestion];
  if (!player || !question || choice < 0 || choice > 3) return getState();

  const correct = choice === question.correct;
  current.answers[playerId] = { choice, correct };

  if (correct) {
    player.score += 600 + timeLeftFor(current) * 20;
  }

  return getState();
}

function moveToNextQuestion(current: GameState) {
  current.phase = "question";
  current.currentQuestion += 1;
  current.revealed = false;
  current.answers = {};
  current.pendingSleIndex = null;
  current.questionStartedAt = Date.now();
}

export function nextStep() {
  const current = store().state;

  if (current.phase === "sle") {
    if (current.currentQuestion >= questions.length - 1) {
      current.phase = "leaderboard";
    } else {
      moveToNextQuestion(current);
    }

    return getState();
  }

  if (current.phase !== "question") return getState();

  const question = questions[current.currentQuestion];
  const atRoundEnd = question.questionIndex === sleRounds[question.roundIndex].questions.length - 1;

  if (atRoundEnd) {
    current.phase = "sle";
    current.pendingSleIndex = question.roundIndex;
    current.revealed = true;
  } else if (current.currentQuestion >= questions.length - 1) {
    current.phase = "leaderboard";
  } else {
    moveToNextQuestion(current);
  }

  return getState();
}
